package io.github.diodeme.ji.error;

import java.time.Duration;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalLong;

/** Transport-neutral structured error generated-code companion. */
public record JiError(
        ErrorCode code,
        Map<String, String> parameters,
        Optional<String> traceId,
        Optional<Duration> retryAfter,
        OptionalLong currentRevision) {
    public JiError {
        Objects.requireNonNull(code, "code");
        parameters = Map.copyOf(parameters);
        Objects.requireNonNull(traceId, "traceId");
        Objects.requireNonNull(retryAfter, "retryAfter");
        Objects.requireNonNull(currentRevision, "currentRevision");
        retryAfter.ifPresent(value -> {
            if (value.isNegative()) {
                throw new IllegalArgumentException("retryAfter must not be negative");
            }
        });
    }
}
